import { useMemo, useState } from 'react';
import {
  JxTable,
  JxTableHeader,
  JxTableBody,
  JxTableRow,
  JxTableHead,
  JxTableCell,
  JxBadge,
  JxPagination,
} from '@jinx-ui/react';

export interface User {
  id: string | number;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const pageUsers = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, currentPage]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
      <JxTable>
        <JxTableHeader>
          <JxTableRow>
            <JxTableHead>Имя</JxTableHead>
            <JxTableHead>Роль</JxTableHead>
            <JxTableHead>Статус</JxTableHead>
          </JxTableRow>
        </JxTableHeader>
        <JxTableBody>
          {pageUsers.map((user) => (
            <JxTableRow key={user.id}>
              <JxTableCell>{user.name}</JxTableCell>
              <JxTableCell>{user.role}</JxTableCell>
              <JxTableCell>
                <JxBadge variant={user.status === 'active' ? 'success' : 'neutral'}>
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </JxBadge>
              </JxTableCell>
            </JxTableRow>
          ))}
        </JxTableBody>
      </JxTable>
      <JxPagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
    </div>
  );
}

